import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";

const server = new McpServer({
  name: "notes-server",
  version: "1.0.0"
});

import { Client } from "@modelcontextprotocol/sdk/client/index.js";

const client = new Client({
  name: "test-client",
  version: "1.0.0"
});

import { z } from "zod";

server.tool(
  "search_notes",
  "Search saved notes for a matching keyword",
  { query: z.string(), limit: z.number().default(5) },
  async ({ query, limit }) => {
    const matches = loadNotes()
      .filter((n) => n.body.toLowerCase().includes(query.toLowerCase()))
      .map((n) => n.title);
    return { content: [{ type: "text", text: matches.slice(0, limit).join("\n") }] };
  }
);

server.resource(
  "all-notes",
  "notes://all",
  async (uri) => ({
    contents: [{ uri: uri.href, text: allNotes().map((n) => n.body).join("\n\n") }]
  })
);

import { ResourceTemplate } from "@modelcontextprotocol/sdk/server/mcp.js";

server.resource(
  "one-note",
  new ResourceTemplate("notes://{noteId}", { list: undefined }),
  async (uri, { noteId }) => {
    const found = findNote(noteId);
    if (!found) throw new Error("No note with that id");
    return { contents: [{ uri: uri.href, text: found.body }] };
  }
);

server.prompt(
  "summarize_note",
  { noteId: z.string() },
  async ({ noteId }) => {
    const found = findNote(noteId);
    return {
      messages: [{
        role: "user",
        content: { type: "text", text: "Summarize this note in two sentences: " + found.body }
      }]
    };
  }
);

import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";

async function main() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
}

main();

import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";

const transport = new StreamableHTTPServerTransport({
  sessionIdGenerator: undefined
});
await server.connect(transport);

import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";

const transport = new StdioClientTransport({ command: "node", args: ["dist/index.js"] });
await client.connect(transport);

const tools = await client.listTools();
const result = await client.callTool({
  name: "search_notes",
  arguments: { query: "vacation" }
});

return {
  content: [
    { type: "text", text: "Added task number 4" }
  ]
};

import { McpError, ErrorCode } from "@modelcontextprotocol/sdk/types.js";

server.tool(
  "delete_note",
  "Delete a note by id",
  { noteId: z.string() },
  async ({ noteId }) => {
    if (!noteExists(noteId)) {
      throw new McpError(ErrorCode.InvalidParams, "No note found with that id");
    }
    removeNote(noteId);
    return { content: [{ type: "text", text: "Deleted the note" }] };
  }
);

// hand rolled, easy to get subtly wrong
process.stdout.write(JSON.stringify({
  jsonrpc: "2.0",
  id: 4,
  result: { content: [{ type: "text", text: "done" }] }
}) + "\n");

// with the SDK, the same result
return { content: [{ type: "text", text: "done" }] };

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";

const server = new McpServer({ name: "tasks-server", version: "1.0.0" });
const tasks = [];

server.tool("add_task", "Add a new task", { title: z.string() }, async ({ title }) => {
  tasks.push(title);
  return { content: [{ type: "text", text: "Added as task number " + tasks.length }] };
});

server.resource("all-tasks", "tasks://all", async (uri) => ({
  contents: [{ uri: uri.href, text: tasks.map((t, i) => (i + 1) + ". " + t).join("\n") }]
}));

server.prompt("plan_my_day", {}, async () => ({
  messages: [{ role: "user", content: { type: "text", text: "Suggest an order for: " + tasks.join(", ") } }]
}));

const transport = new StdioServerTransport();
await server.connect(transport);

server.tool(
  "convert_temp",
  "Convert a temperature between celsius and fahrenheit",
  { value: z.number(), toUnit: z.enum(["celsius", "fahrenheit"]) },
  async ({ value, toUnit }) => {
    const result = toUnit === "fahrenheit" ? value * 9 / 5 + 32 : (value - 32) * 5 / 9;
    return { content: [{ type: "text", text: String(result) }] };
  }
);
